<?php get_header(); ?>
<?php if ( is_home() && ! is_paged() ) : ?>
<section class="landing-intro"><p class="eyebrow">THE SCREENING ROOM / <?php echo esc_html( msc_screen_identity()['label'] ); ?></p><h1><?php echo esc_html( msc_screen_identity()['tagline'] ); ?></h1><p>Discover your next great watch, explore every episode, and meet the people who bring it all to life.</p><a class="text-link" href="<?php echo esc_url( get_post_type_archive_link( 'msc_movie' ) ?: home_url( '/' ) ); ?>">Explore the collection <span aria-hidden="true"><span class="arrow" aria-hidden="true"></span></span></a><span class="intro-orbit" aria-hidden="true"></span></section>
<?php foreach ( array( 'msc_movie' => array( '01', 'At the movies' ), 'msc_show' => array( '02', 'On the small screen' ), 'msc_episode' => array( '03', 'One episode at a time' ), 'msc_person' => array( '04', 'Behind the stories' ) ) as $type => $section ) : if ( ! post_type_exists( $type ) ) { continue; } ?>
<section class="collection"><div class="section-heading"><h2><span><?php echo esc_html( $section[0] ); ?></span><?php echo esc_html( $section[1] ); ?></h2><a class="text-link" href="<?php echo esc_url( get_post_type_archive_link( $type ) ); ?>">View all <span class="arrow" aria-hidden="true"></span></a></div><?php msc_screen_grid( $type, 4 ); ?></section>
<?php endforeach; ?>
<?php else : ?>
<section class="archive-heading"><p class="eyebrow">THE COLLECTION</p><h1><?php echo is_search() ? 'Search results' : esc_html( wp_strip_all_tags( get_the_archive_title() ?: 'Stories' ) ); ?></h1><?php if ( is_search() ) { echo '<p>Results for “' . esc_html( get_search_query() ) . '”</p>'; } ?></section>
<div class="catalog-grid archive-grid"><?php while ( have_posts() ) : the_post(); $r = msc_screen_record(); if ( $r ) { \MSC\Presentation::card( $r ); } else { ?><article class="catalog-card"><h2><a href="<?php the_permalink(); ?>"><?php the_title(); ?></a></h2><?php the_excerpt(); ?></article><?php } endwhile; if ( ! have_posts() && ! $wp_query->post_count ) { echo '<p class="empty-state">No stories found. Try another search or browse a collection above.</p>'; } ?></div><div class="pagination"><?php the_posts_pagination(); ?></div>
<?php endif; get_footer(); ?>
